    /* Toggle switch style */
    .switch {
        position: relative;
        display: inline-block;
        width: 46px;
        height: 24px;
    }

    .switch input {
        display: none;
    }

    .slider {
        position: absolute;
        cursor: not-allowed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: #ccc;
        transition: 0.4s;
        border-radius: 34px;
    }

    .slider:before {
        position: absolute;
        content: &quot;&quot;;
        height: 18px;
        width: 18px;
        left: 3px;
        bottom: 3px;
        background-color: white;
        transition: 0.4s;
        border-radius: 50%;
    }

    input:checked+.slider {
        background-color: currentColor;
    }

    input:checked+.slider:before {
        transform: translateX(22px);
    }

    /* Warna per tipe permission */
    .switch.view {
        color: #2196f3;
    }

    /* Biru */
    .switch.edit {
        color: #ff9800;
